-- 仅用于隔离测试的原表子集，绝不由应用初始化生产库。
CREATE TABLE TSS_BCOMP_CONF (BCOMP_INDEX BIGINT PRIMARY KEY, BCOMP_NAME VARCHAR(100), BCOMP_TYPE VARCHAR(1));
CREATE TABLE TSS_BCOMP_TASK (BCOMP_INDEX BIGINT, TASK_BUSI_DATE VARCHAR(8), TASK_BATCH VARCHAR(20), BCOMP_TIME_NODE VARCHAR(20), VERIFY_BUSINESS_DATE VARCHAR(8), TASK_STATE VARCHAR(1), TASK_RESULT VARCHAR(1), BEGIN_DATETIME VARCHAR(14), END_DATETIME VARCHAR(14), FTASK_REASON VARCHAR(2000), FILE1_ACOUNT BIGINT, FILE2_ACOUNT BIGINT);
CREATE TABLE TSS_BCOMP_DATABASE_CONFIG (DATABASE_ID BIGINT PRIMARY KEY, DATABASE_URL VARCHAR(1000), DATABASE_USER VARCHAR(100), DATABASE_PASSWORD VARCHAR(1000), DATABASE_DRIVER VARCHAR(200), DATABASE_ENCRYPTION VARCHAR(1), DATABASE_GENERATERKEY VARCHAR(200));
CREATE TABLE TSS_BCOMP_TABLE_SQL (BCOMP_INDEX BIGINT, ORIG_DATABASE_ID BIGINT, DEST_DATABASE_ID BIGINT, ORIG_SQL VARCHAR(4000), DEST_SQL VARCHAR(4000));
CREATE TABLE TSS_BCOMP_FIELD (BCOMP_INDEX BIGINT, FIELD_NAME VARCHAR(100));
